/* Exact original submitted HTML source: presentation only; do not edit. */
window.MON_ARCHIVE_SOURCE = "<!DOCTYPE html>\r\n<html lang=\"fil\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Sa Likod ng mga Lunes | Ma'am Roan</title>\r\n</head>\r\n\r\n<body>\r\n\r\n    <header>\r\n        <h1>Sa Likod ng mga Lunes, May mga Alaalang Mananatili</h1>\r\n        <p><em>Isang liham ng pasasalamat para kay Ma'am Roan</em></p>\r\n    </header>\r\n\r\n    <main>\r\n\r\n        <!-- Every meaningful story begins somewhere. -->\r\n\r\n        <section id=\"introduction\">\r\n\r\n            <p>\r\n                May mga taong nakikilala natin nang hindi natin\r\n                inaasahang magiging bahagi sila ng mga alaalang\r\n                dadalhin natin sa paglipas ng panahon. Minsan,\r\n                nagsisimula ang lahat sa isang simpleng pagkikita,\r\n                isang maikling kuwentuhan, o kahit sa isang pangalang\r\n                nababasa lamang natin sa ating iskedyul. Hindi natin\r\n                agad alam kung ano ang magiging kuwento ng ating\r\n                pagkakakilala sa kanila. Ngunit habang lumilipas\r\n                ang panahon, may mga pagkakataong napagtatanto\r\n                nating ang mga simpleng sandali pala ang siyang\r\n                nagiging pinakamahalagang bahagi ng ating mga alaala.\r\n            </p>\r\n\r\n            <p>\r\n                At ganoon po nagsimula ang kuwento ng pagkakakilala\r\n                ko sa inyo, Ma'am Roan.\r\n            </p>\r\n\r\n            <p>\r\n                Noong una kong makita ang aming iskedyul para sa\r\n                ikalawang taon, napansin kong dalawa ang may\r\n                apelyidong Cochanco sa listahan ng aming mga propesor.\r\n                Natuwa po ako, ngunit hindi rin maikakailang may\r\n                kasamang kaba. Isipin po ba naman, mag-asawa ang\r\n                dalawa sa magiging guro namin! At ayon pa sa aming\r\n                mga narinig, tila ngayon lamang nangyari na kapwa\r\n                namin magiging propesor ang mag-asawang guro.\r\n                Kaya hindi ko po alam kung mas dapat ba akong\r\n                matuwa o kabahan. HAHAHAHA.\r\n            </p>\r\n\r\n            <p>\r\n                Dumating ang unang Lunes, ang unang klase ng aming\r\n                linggo, at doon nagsimula ang aming pagkakakilala.\r\n                Sa unang araw na iyon, nagkaroon tayo ng pagkakataong\r\n                magkuwentuhan at magpakilala sa isa't isa. Marami\r\n                sa aming mga kaklase ang nagsabing mabait kayo at\r\n                magaan kasama. Gayunpaman, kahit marami na akong\r\n                narinig na magagandang bagay tungkol sa inyo,\r\n                hindi pa rin tuluyang nawawala ang kaunting kaba.\r\n                Marahil dahil bago pa lamang ang lahat, at kailangan\r\n                ko rin munang mas makilala kayo.\r\n            </p>\r\n\r\n            <p>\r\n                Habang lumilipas ang mga linggo, unti-unti ring\r\n                napalitan ng mga simpleng interaksiyon ang dating\r\n                pag-aalinlangan. Sa inyong mga kuwento, na kung\r\n                minsan ay parang laging may kasunod, sa mga tawanan,\r\n                at sa mga sandaling nagiging mas masigla ang aming\r\n                klase, mas nakilala ko po kayo hindi lamang bilang\r\n                aming propesor sa IT-WS02, kundi bilang isang gurong\r\n                may sariling paraan upang gawing mas magaan at\r\n                mas makulay ang aming mga araw sa klase.\r\n            </p>\r\n\r\n        </section>\r\n\r\n        <!-- Memories that became part of the story. -->\r\n\r\n        <section id=\"classroom-memories\">\r\n\r\n            <p>\r\n                Aaminin ko rin po na hindi kami palaging tahimik\r\n                at seryoso sa inyong klase. May mga pagkakataong\r\n                nadadala kami ng tawanan at kuwentuhan, lalo na\r\n                sa aming puwesto. May mga sandali ring nagiging\r\n                maingay kami nang hindi namamalayan. Kaya nais\r\n                ko pong humingi ng paumanhin kung minsan ay\r\n                nakadagdag kami sa inyong pagod o nakasagabal\r\n                sa inyong pagtuturo. Pasensya na rin po sa mga\r\n                pagkakataong hindi namin agad napapansin na\r\n                sumosobra na pala kami sa ingay. Sana po ay hindi\r\n                ninyo kami masyadong dinamdam sa mga pagkakataong iyon.\r\n            </p>\r\n\r\n            <p>\r\n                At siyempre, hindi ko rin po malilimutan ang\r\n                pagkakataong nagkaroon kami ng zero dahil sa isang\r\n                pangyayaring may kinalaman sa pagsigaw ng sagot\r\n                habang nagse-seatwork. HAHAHAHA. Isa iyon sa mga\r\n                karanasang tiyak na hindi basta-basta makakalimutan\r\n                ng aming klase. Ngunit higit pa sa nangyari,\r\n                pinahahalagahan ko po ang pagkakataong muli ninyo\r\n                kaming pinagbigyan makalipas ang ilang linggo.\r\n                Maraming salamat po sa inyong pang-unawa at sa\r\n                pagkakataong maitama namin ang aming pagkukulang.\r\n                Hindi po namin iyon basta itinuturing na simpleng\r\n                pangalawang pagkakataon, kundi isang paalala na\r\n                may mga gurong handang umunawa at magbigay muli\r\n                ng tiwala sa kanilang mga estudyante.\r\n            </p>\r\n\r\n            <p>\r\n                Hindi rin po mawawala sa aking mga alaala ang\r\n                pagkakataong tumulong kami sa paggawa ng garland.\r\n                Maaaring isa lamang itong simpleng gawain, ngunit\r\n                naging isa rin itong masayang karanasan na maaalala\r\n                ko. Maraming salamat din po sa meryenda, Ma'am!\r\n                At siyempre, hindi rin po namin palalampasin ang\r\n                dagdag na puntos sa exam. HAHAHAHA. Maliliit na\r\n                bagay man ang mga iyon, bahagi pa rin po sila\r\n                ng mga alaalang nagbigay saya sa aming semestre.\r\n            </p>\r\n\r\n        </section>\r\n\r\n        <!-- Achievement unlocked: A memorable Lab 1. -->\r\n\r\n        <section id=\"lab-1\">\r\n\r\n            <h2>One Special Memory</h2>\r\n\r\n            <p>\r\n                Ngunit sa dami ng mga pangyayaring iyon, may isang\r\n                simpleng sandali na talagang hindi ko po malilimutan.\r\n            </p>\r\n\r\n            <p><strong>Ang araw na na-appreciate ninyo ang aking Lab 1.</strong></p>\r\n\r\n            <p>\r\n                Maaaring para sa iba ay isa lamang iyong karaniwang\r\n                gawain na ipinasa at binigyan ng marka. Ngunit para\r\n                sa akin, higit pa roon ang naging kahulugan nito.\r\n                Nang malaman kong nagustuhan ninyo ang kalinisan\r\n                at kaayusan ng aking ipinasa, at nang marinig kong\r\n                ako lamang ang nakakuha ng perpektong marka,\r\n                hindi ko po maikakailang biglang lumaki ang aking\r\n                ngiti. Mula sa pagiging lowbat, biglang naging\r\n                full charge na naman! HAHAHAHA.\r\n            </p>\r\n\r\n            <p>\r\n                Bilang isang taong medyo maarte pagdating sa mga\r\n                ipinapasang gawain, napakalaking bagay po para\r\n                sa akin na mapansin ninyo ang mga detalyeng\r\n                pinaghirapan kong ayusin. Sa likod ng isang malinis\r\n                at maayos na output ay may oras, pag-iisip, at\r\n                pagsisikap na hindi palaging nakikita. Kaya nang\r\n                mapansin ninyo ang mga bagay na iyon, pakiramdam\r\n                ko ay hindi lamang ang aking output ang inyong\r\n                pinahalagahan, kundi pati na rin ang pagsisikap\r\n                na inilaan ko rito.\r\n            </p>\r\n\r\n            <p>\r\n                Higit sa marka, ang papuri ninyo ang naging dagdag\r\n                na inspirasyon upang mas pagbutihin ko pa ang aking\r\n                mga susunod na gawain. Mas lalo po akong ginanahang\r\n                panatilihin ang kalidad ng aking mga ipinapasa.\r\n                Siyempre, ayaw ko rin naman pong masira ang\r\n                magandang impresyong naibigay ko sa inyo. HAHAHAHA.\r\n            </p>\r\n\r\n        </section>\r\n\r\n        <!-- Lessons beyond the subject. -->\r\n\r\n        <section id=\"lessons\">\r\n\r\n            <p>\r\n                Ma'am, marahil hindi ninyo na matandaan ang lahat\r\n                ng maliliit na pangyayaring ito. Maaaring para sa\r\n                inyo ay bahagi lamang ang mga iyon ng karaniwang\r\n                araw ng pagtuturo. Ngunit para sa isang estudyante,\r\n                may mga simpleng salita, pagkakataon, at kilos\r\n                ang gurong hindi agad nawawala sa isip. Minsan,\r\n                hindi man natin namamalayan, ang isang papuri ay\r\n                nagiging inspirasyon, ang isang pagkakataon ay\r\n                nagiging aral, at ang isang simpleng kuwentuhan\r\n                ay nagiging alaalang kusang binabalikan.\r\n            </p>\r\n\r\n            <p>\r\n                Doon ko rin po mas naunawaan na ang pagiging guro\r\n                ay hindi lamang nasusukat sa mga araling naituturo\r\n                o sa mga markang naibibigay. May mga bagay na\r\n                naiiwan sa mga estudyante na hindi matatagpuan\r\n                sa anumang module o presentation. Maaaring ito\r\n                ay tiwala, pang-unawa, inspirasyon, o ang simpleng\r\n                pakiramdam na napapansin at pinahahalagahan sila.\r\n                At sa sarili kong karanasan, ilan po sa mga bagay\r\n                na iyon ang naging bahagi ng semestre ko kasama kayo.\r\n            </p>\r\n\r\n        </section>\r\n\r\n        <!-- A message of gratitude. -->\r\n\r\n        <section id=\"gratitude\">\r\n\r\n            <p>\r\n                Kung may isang bagay man akong nais iparating,\r\n                iyon ay ang aking taos-pusong pasasalamat.\r\n                Salamat po sa mga aral na itinuro ninyo sa IT-WS02,\r\n                sa mga kuwentong nagbibigay-buhay sa aming klase,\r\n                sa inyong pang-unawa, sa mga pagkakataong ibinigay\r\n                ninyo, at sa mga simpleng papuring maaaring hindi\r\n                ninyo gaanong pinapansin ngunit malaki ang\r\n                naidudulot sa isang estudyanteng tulad ko.\r\n            </p>\r\n\r\n            <p>\r\n                At kung dumating man ang panahong kayo naman ang\r\n                mangailangan ng tulong, Ma'am, sana po ay malaman\r\n                ninyong narito lamang ako at handang tumulong sa\r\n                abot ng aking makakaya. Maaaring hindi ko masuklian\r\n                nang lubos ang lahat ng kabutihang ipinakita ninyo,\r\n                ngunit umaasa akong sa simpleng paraan ay maibabalik\r\n                ko rin ang kabutihang ipinadama ninyo sa amin.\r\n            </p>\r\n\r\n        </section>\r\n\r\n        <!-- The most important part of this page. -->\r\n\r\n        <section id=\"final-message\">\r\n\r\n            <h2>Final Message</h2>\r\n\r\n            <p>\r\n                <strong>\r\n                    Sa huli, Ma'am Roan, maaaring isa lamang akong\r\n                    pangalan sa talaan ng inyong mga estudyante,\r\n                    ngunit kayo ay isa sa mga gurong magkakaroon\r\n                    ng sariling pahina sa kuwento ng aking pag-aaral.\r\n                </strong>\r\n            </p>\r\n\r\n            <p>\r\n                At marahil, iyon ang isa sa pinakamagandang bagay\r\n                tungkol sa pagiging estudyante. Hindi lamang tayo\r\n                umaalis sa isang klase na may dalang bagong kaalaman,\r\n                kundi mayroon din tayong mga kuwentong hindi nakasulat\r\n                sa ating mga kuwaderno, mga aral na hindi kasama\r\n                sa pagsusulit, at mga taong hindi man natin palaging\r\n                makakasama ay mananatiling bahagi ng ating mga alaala.\r\n            </p>\r\n\r\n            <p>\r\n                Kaya sa bawat Lunes na minsang naging simula lamang\r\n                ng aming linggo, natutuwa po akong naging bahagi\r\n                kayo ng mga kuwentong nabuo sa panahong ito.\r\n                At kahit dumating ang araw na matapos na ang aming\r\n                mga klase sa inyo, umaasa akong mananatili ang\r\n                masasayang alaala, mga aral, at pasasalamat\r\n                na nabuo sa likod ng mga Lunes na iyon.\r\n            </p>\r\n\r\n            <p>\r\n                Maraming salamat po, Ma'am Roan. Hindi lamang po\r\n                bilang aming propesor, kundi bilang isang gurong\r\n                nag-iwan ng magagandang alaala sa isa sa inyong\r\n                mga estudyante.\r\n            </p>\r\n\r\n        </section>\r\n\r\n    </main>\r\n\r\n    <footer>\r\n\r\n        <blockquote>\r\n            <em>\r\n                May mga pagkikitang nagtatapos sa pagtatapos\r\n                ng klase, ngunit may mga alaalang hindi kasabay\r\n                na natatapos.\r\n            </em>\r\n        </blockquote>\r\n\r\n        <p><strong>Nang may lubos na pasasalamat at paghanga,</strong></p>\r\n\r\n        <p>\r\n            <em>\r\n                Isang estudyanteng minsang kinabahan, ngunit ngayo'y\r\n                masayang nagpapasalamat na naging estudyante po ninyo.\r\n            </em>\r\n        </p>\r\n\r\n        <p>\r\n            <strong>— Rollenn Mike Fabian</strong><br>\r\n            BSIT 2A\r\n        </p>\r\n\r\n    </footer>\r\n\r\n</body>\r\n</html>";
